export const sendChatMessageBodyContactCardUsernameRegExp = new RegExp(
  "^[\\w.\\-@]{1,50}$",
);

export const sendChatMessageBodyContactCardPhoneRegExp = new RegExp(
  "^[+\\d\\s().\\\/\\-]{0,30}$",
);

